// Worker entry: OpenNext's generated fetch handler plus a cron trigger that
// runs scheduled re-checks through the app's own /api/cron/recheck route.
// Built by wrangler after `opennextjs-cloudflare build`.

// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  APP_URL?: string;
  CRON_SECRET?: string;
}

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return console.warn("CRON_SECRET is not set; skipping scheduled re-checks.");
    const base = (env.APP_URL || "https://productroot.invalid").replace(/\/+$/, "");
    const req = new Request(`${base}/api/cron/recheck`, { method: "POST", headers: { "x-cron-secret": env.CRON_SECRET } });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => console.log("recheck", res.status, await res.text())),
    );
  },
};
